import test, { afterEach } from 'node:test'
import assert from 'node:assert/strict'
import { useFakeSettings, stubMeson, makeWorld, swapId, swapRecord, refusal, sleep, texts, MOVING, DONE } from './helpers.mjs'

useFakeSettings()
const { watchSwap, stopWatchingChannel } = await import('../src/watch.js')
const { getSwaps, listSwapsForAddress } = await import('../src/meson.js')
const { getTicket, forgetTicket } = await import('../src/ticket-state.js')
const { recoverTickets } = await import('../src/recover.js')
const { onTicketMessage } = await import('../src/tickets.js')
const { CLOSING_SOON, buildSwapEmbed } = await import('../src/render.js')
const { extractCandidates, extractAddressCandidates } = await import('../src/extract.js')

// =============================================================================
//   Helpers
// =============================================================================

// A failed test must not leave a swap being followed: its checks would disturb the next test and keep the process alive.
afterEach(() => { for (let i = 1; i <= 20; i++) stopWatchingChannel(`c${i}`) })

/** The closing messages among what the bot posted. */
const closings = (posted) => texts(posted).filter((x) => x.includes('Transaction Completed'))

/** Start following one swap whose details embed is `embed`. */
async function follow (world, embed, id) {
  const t = getTicket(world.channel.id)
  const entry = { n: 1, swapId: id, message: embed, latest: (await getSwaps([id])).get(id) }
  t.swaps.push(entry)
  await watchSwap(t, entry)
  return entry
}

// =============================================================================
//   A failed post never ends a follow-up
// =============================================================================

test('a failed ⏳ post is retried, and the swap is still followed to its closing message', async () => {
  const id = swapId(1)
  const events = { [id]: MOVING }
  stubMeson({ events })
  const world = makeWorld('c1')
  let failures = 1
  const embed = world.message(1, world.me, {}, { failReply: () => (failures-- > 0 ? new Error('Discord 500') : null) })
  await follow(world, embed, id)
  assert.equal(texts(world.posted).length, 0)
  await sleep(1500)
  assert.equal(texts(world.posted).filter((x) => x.startsWith('⏳')).length, 1, 'the ⏳ is posted on the next check')
  events[id] = DONE
  await sleep(2500)
  assert.equal(closings(world.posted).length, 1)
  stopWatchingChannel('c1')
})

test('a failed closing message for an already finished swap is retried', async () => {
  const id = swapId(2)
  stubMeson({ events: { [id]: DONE } })
  const world = makeWorld('c2')
  let failures = 1
  const embed = world.message(1, world.me, {}, { failReply: () => (failures-- > 0 ? new Error('Discord 500') : null) })
  await follow(world, embed, id)
  assert.equal(closings(world.posted).length, 0)
  await sleep(2000)
  assert.equal(closings(world.posted).length, 1)
  stopWatchingChannel('c2')
})

test('a refused post is not repeated on every check', async () => {
  const id = swapId(3)
  const events = { [id]: MOVING }
  stubMeson({ events })
  const world = makeWorld('c3')
  const embed = world.message(1, world.me)
  await follow(world, embed, id)
  let refused = 0
  embed.reply = async () => { refused++; throw refusal() }
  events[id] = DONE
  await sleep(4500)
  assert.equal(refused, 1)
  stopWatchingChannel('c3')
})

