test('a message seen both live and in the history is handled once', async () => {
  stubMeson()
  const world = makeWorld('c4')
  const m = world.message(50, world.user, { content: `my swap ${swapId(4)} is stuck` })
  world.channel.history = [m]
  const recovering = recoverTickets(world.client)
  onTicketMessage(m)
  await recovering
  await sleep(300)
  assert.equal(texts(world.posted).filter((x) => x.startsWith('❓')).length, 1)
})

/** A ticket whose two swaps were posted before a restart: two details embeds, each with its ⏳. */
function ticketWithTwoSwaps (world, a, b) {
  const embed = (id) => ({ title: 'Meson swap — Pending', url: `https://explorer.meson.fi/swap/${id}` })
  world.channel.history = [
    world.message(10, world.me, { embeds: [embed(a)] }),
    world.message(11, world.me, { content: '⏳ x', reference: { messageId: '10' } }),
    world.message(12, world.me, { embeds: [embed(b)] }),
    world.message(13, world.me, { content: '⏳ x', reference: { messageId: '12' } }),
  ]
}

test('two swaps finishing while the bot was down: only the last closing message says "closed soon"', async () => {
  const [a, b] = [swapId(5), swapId(6)]
  stubMeson({ events: { [a]: DONE, [b]: DONE } })
  const world = makeWorld('c5')
  ticketWithTwoSwaps(world, a, b)
  await recoverTickets(world.client)
  await sleep(300)
  const all = closings(world.posted)
  assert.equal(all.length, 2)
  assert.equal(all.filter((x) => x.includes(CLOSING_SOON)).length, 1)
  assert.ok(all[1].includes(CLOSING_SOON))
})

test('recovering the same ticket twice (a reconnect) posts nothing twice', async () => {
  const [a, b] = [swapId(7), swapId(8)]
  stubMeson({ events: { [a]: DONE, [b]: MOVING } })
  const world = makeWorld('c6')
  ticketWithTwoSwaps(world, a, b)
  world.channel.history.push(world.message(14, world.user, { content: `what about ${swapId('c')}` }))
  await recoverTickets(world.client)
  await sleep(300)
  // The first pass did real work: a closing message for the finished swap, and an answer to the missed message.
  assert.equal(closings(world.posted).length, 1)
  assert.equal(texts(world.posted).filter((x) => x.startsWith('❓')).length, 1)
  const before = world.posted.length
  // A user message from the connection gap, older than the bot's last post (the bot can still post during a drop), must still be answered.
  world.channel.history.push(world.message(15, world.user, { content: `and ${swapId('c').replace(/c/g, 'e')}` }))
  await recoverTickets(world.client)
  await sleep(300)
  assert.equal(world.posted.length, before + 1, 'only the new message gets a reply')
  stopWatchingChannel('c6')
})

test('a ⏳ left behind by a stop between the two steps is removed on recovery', async () => {
  const id = swapId(9)
  stubMeson({ events: { [id]: DONE } })
  const world = makeWorld('c7')
  const processing = world.message(11, world.me, { content: '⏳ x', reference: { messageId: '10' } })
  world.channel.history = [
    world.message(10, world.me, { embeds: [{ title: 'Meson swap — Done', url: `https://explorer.meson.fi/swap/${id}` }] }),
    processing,
    world.message(12, world.me, { content: '**✅ Transaction Completed**', reference: { messageId: '10' } }),
  ]
  await recoverTickets(world.client)
  await sleep(100)
  assert.equal(processing.deleted, true)
  assert.equal(world.posted.length, 0)
})

// =============================================================================
//   Status reason and support reply
// =============================================================================

/** Confirmed EXECUTED, no release: Releasing, and stuck if the swap is also overdue. */
const EXECUTED = [{ name: 'EXECUTED', hash: '0xaa' }]

/** A failed attempt only, an hour from the deadline: nothing on-chain, so the explorer already shows Expired. */
const EXPIRED = [{ name: 'EXECUTED:FAILED', hash: '0xaa' }]

/** The 🔎 replies among what the bot posted. */
const supports = (posted) => texts(posted).filter((x) => x.startsWith('🔎'))

test('the embed gives the reason for a status; the support note is a reply, like the ⏳', async () => {
  const id = swapId('6')
  stubMeson({ events: { [id]: EXECUTED }, overdue: [id] })
  const world = makeWorld('c14')
  const embed = world.message(1, world.me)
  const entry = await follow(world, embed, id)
  const description = buildSwapEmbed(entry.latest).data.description
  assert.ok(description.includes('received by the LP'))
  assert.ok(!description.includes('support team'))
  assert.equal(supports(world.posted).length, 1)
  assert.ok(supports(world.posted)[0].includes('taking longer than usual'))
  assert.equal(texts(world.posted).filter((x) => x.startsWith('⏳')).length, 0)
  await sleep(1500)
  assert.equal(supports(world.posted).length, 1, 'a later check does not post it again')
  assert.ok(buildSwapEmbed(entry.latest, { withSupportNote: true }).data.description.includes('support team'), '/meson-query has no reply to carry it')
})

test('a Releasing swap whose LP has no funds yet does not claim it has', async () => {
  const id = swapId('8')
  stubMeson({ events: { [id]: [{ name: 'BONDED', hash: '0xaa' }, { name: 'RELEASING' }] } })
  const found = (await getSwaps([id])).get(id)
  assert.equal(found.status.label, 'Releasing')
  assert.ok(!found.status.detail.includes('LP'))
})

test('one reply changes ⏳ → 🔎 → ⏳ in place, and is deleted by the closing message', async () => {
  const id = swapId('7')
  const events = { [id]: MOVING }
  stubMeson({ events })
  const world = makeWorld('c15')
  const embed = world.message(1, world.me)
  const entry = await follow(world, embed, id)
  const reply = entry.processing
  assert.ok(reply.content.startsWith('⏳'))
  events[id] = EXPIRED
  await sleep(2500)
  assert.equal(entry.support, reply)
  assert.equal(entry.processing, null)
  assert.ok(reply.content.startsWith('🔎'))
  events[id] = MOVING
  await sleep(2500)
  assert.equal(entry.processing, reply)
  assert.equal(entry.support, null)
  assert.ok(reply.content.startsWith('⏳'))
  events[id] = EXPIRED
  await sleep(2500)
  assert.ok(reply.content.startsWith('🔎'))
  assert.equal(world.posted.length, 1, 'all of that was one message')
  events[id] = DONE
  await sleep(2500)
  assert.equal(reply.deleted, true)
  assert.equal(closings(world.posted).length, 1)
})

test('a reply that cannot be edited is replaced, and never left up next to the new one', async () => {
  const id = swapId('5')
  const events = { [id]: MOVING }
  stubMeson({ events })
  const world = makeWorld('c18')
  const entry = await follow(world, world.message(1, world.me), id)
  const hourglass = entry.processing
  hourglass.edit = async () => { throw new Error('Discord 500') }
  events[id] = EXPIRED
  await sleep(2500)
  assert.equal(supports(world.posted).length, 1)
  assert.equal(hourglass.deleted, true)
  assert.equal(entry.processing, null)
  const support = entry.support
  support.edit = async () => { throw new Error('Discord 500') }
  events[id] = MOVING
  await sleep(2500)
  assert.equal(support.deleted, true)
  assert.equal(entry.support, null)
  assert.ok(entry.processing, 'a new ⏳ is posted')
})

