test('a reconnect waits for a message being handled, so its swap is not lost', async () => {
  const id = swapId('9')
  stubMeson({ events: { [id]: MOVING }, search: { [id]: { swapId: id } } })
  const stubbed = globalThis.fetch
  globalThis.fetch = async (url) => { await sleep(100); return stubbed(url) } // the swap is posted after about 300 ms
  const world = makeWorld('c20')
  const message = world.message(80, world.user, { content: `swap ${id}` })
  world.channel.history = [message]
  // As from Discord: an embed's fields come back readable, and the page is as it was when it was asked for.
  world.channel.messages.fetch = async () => {
    const page = new Map(world.channel.history.map((m) => [m.id, { ...m, embeds: m.embeds.map((e) => e.data ?? e) }]))
    await sleep(500)
    return page
  }
  onTicketMessage(message)
  await recoverTickets(world.client)
  await sleep(100)
  assert.equal(getTicket('c20').swaps.length, 1)
  assert.equal(world.posted.filter((p) => p.embeds?.length).length, 1)
})

test('every support reply says the funds are safe, without promising completion', async () => {
  const [stuck, expired, unlocked, failed] = [swapId('4'), swapId('3'), swapId('2'), swapId('1')]
  stubMeson({
    events: { [stuck]: EXECUTED, [expired]: EXPIRED, [unlocked]: [...EXECUTED, { name: 'UNLOCKED', hash: '0xbb' }], [failed]: EXPIRED },
    overdue: [stuck],
    distant: [failed],
  })
  const found = await getSwaps([stuck, expired, unlocked, failed])
  const statuses = [stuck, expired, unlocked, failed].map((id) => found.get(id).status)
  assert.deepEqual(statuses.map((s) => s.label), ['Releasing', 'Expired', 'Unlocked', 'Failed'])
  assert.equal(statuses[0].stuck, true)
  for (const s of statuses) {
    assert.ok(s.supportNote.includes('Your funds are safe'))
    assert.ok(!s.supportNote.includes('shortly'))
  }
})

