test('after a restart, an embed from before this change gets its 🔎 once, and an existing 🔎 is kept', async () => {
  const [a, b] = [swapId('a1'.charAt(1)), swapId('b')]
  stubMeson({ events: { [a]: EXECUTED, [b]: EXECUTED }, overdue: [a, b] })
  const world = makeWorld('c17')
  const embed = (id) => ({ title: 'Meson swap — Releasing', url: `https://explorer.meson.fi/swap/${id}` })
  const details = world.message(10, world.me, { embeds: [embed(a)] })
  world.channel.history = [
    details,
    world.message(12, world.me, { embeds: [embed(b)] }),
    world.message(13, world.me, { content: '🔎 **Swap #2** · This transaction is taking longer than usual — our support team will look into it.', reference: { messageId: '12' } }),
  ]
  await recoverTickets(world.client)
  await sleep(300)
  assert.equal(supports(world.posted).length, 1, 'only the swap without one')
  assert.ok(supports(world.posted)[0].includes('Swap #1'))
  assert.ok(details.embeds[0].data.description.includes('received by the LP'), 'the old wording on the embed is replaced')
  const before = world.posted.length
  await recoverTickets(world.client)
  await sleep(300)
  assert.equal(world.posted.length, before, 'a second recovery posts nothing')
})

