/** Make a world's history read as it does from Discord (embed fields readable, messages older than this process), so a test can restart the bot on it: forget the ticket, then recover. */
function restartable (world) {
  world.channel.messages.fetch = async () => new Map(world.channel.history.map((m) => [m.id, { ...m, createdTimestamp: 0, embeds: m.embeds.map((e) => e.data ?? e) }]))
  return async () => {
    forgetTicket(world.channel.id)
    await recoverTickets(world.client)
    await sleep(100)
  }
}

test('the same unknown value gets one "couldn\'t find", also after a restart', async () => {
  const unknown = `0x${'d1'.repeat(32)}`
  stubMeson()
  const world = makeWorld('w6')
  const restart = restartable(world)
  const first = world.message(91, world.user, { content: `hash ${unknown}` })
  world.channel.history = [first]
  onTicketMessage(first)
  await sleep(200)
  onTicketMessage(world.message(92, world.user, { content: `again: ${unknown.toUpperCase().replace('0X', '0x')}` }))
  await sleep(200)
  assert.equal(world.posted.length, 1)
  await restart()
  onTicketMessage(world.message(2000, world.user, { content: unknown }))
  await sleep(200)
  assert.equal(world.posted.length, 1, 'not after a restart either')
  onTicketMessage(world.message(2001, world.user, { content: `other 0x${'d2'.repeat(32)}` }))
  await sleep(200)
  assert.equal(world.posted.length, 2, 'a new value still gets its answer')
})

test('a value already told about is still looked up, so a swap that appears later is shown', async () => {
  const id = `0x${'d3'.repeat(32)}`
  const search = {}
  stubMeson({ search, events: { [id]: DONE } })
  const world = makeWorld('w7')
  onTicketMessage(world.message(93, world.user, { content: id }))
  await sleep(200)
  assert.ok(world.posted[0].content.startsWith('❓'))
  search[id] = { swapId: id }
  onTicketMessage(world.message(94, world.user, { content: id }))
  await sleep(200)
  assert.equal(world.posted.filter((p) => p.embeds?.[0]?.data?.title?.startsWith('Meson swap')).length, 1)
})

test('the same wallet gets one answer, also after a restart', async () => {
  const wallet = '0x' + 'd4'.repeat(20)
  stubMeson({ walletSwaps: [swapRecord(swapId('a'), DONE)] })
  const world = makeWorld('w8')
  const restart = restartable(world)
  const first = world.message(95, world.user, { content: wallet })
  world.channel.history = [first]
  onTicketMessage(first)
  await sleep(200)
  onTicketMessage(world.message(96, world.user, { content: wallet }))
  await sleep(200)
  assert.equal(world.posted.length, 1)
  await restart()
  onTicketMessage(world.message(2002, world.user, { content: wallet }))
  await sleep(200)
  assert.equal(world.posted.length, 1, 'not after a restart either')
})

test('a value named in a wallet embed gets no separate "couldn\'t find" later, also after a restart', async () => {
  const wallet = '0x' + 'd5'.repeat(20)
  const unknown = `0x${'d6'.repeat(32)}`
  stubMeson({ walletSwaps: [swapRecord(swapId('a'), DONE)] })
  const world = makeWorld('w9')
  const restart = restartable(world)
  const first = world.message(97, world.user, { content: `${unknown} ${wallet}` })
  world.channel.history = [first]
  onTicketMessage(first)
  await sleep(200)
  onTicketMessage(world.message(98, world.user, { content: unknown }))
  await sleep(200)
  assert.equal(world.posted.length, 1)
  await restart()
  onTicketMessage(world.message(2003, world.user, { content: unknown }))
  await sleep(200)
  assert.equal(world.posted.length, 1, 'not after a restart either')
})

test('a swap pasted again gets no second embed, also after a restart', async () => {
  const id = `0x${'d7'.repeat(32)}`
  stubMeson({ search: { [id]: { swapId: id } }, events: { [id]: DONE } })
  const world = makeWorld('w10')
  const restart = restartable(world)
  const first = world.message(99, world.user, { content: id })
  world.channel.history = [first]
  onTicketMessage(first)
  await sleep(200)
  const posted = world.posted.length
  onTicketMessage(world.message(100, world.user, { content: id }))
  await sleep(200)
  assert.equal(world.posted.length, posted)
  await restart()
  onTicketMessage(world.message(2004, world.user, { content: id }))
  await sleep(200)
  assert.equal(world.posted.length, posted, 'not after a restart either')
})

test('a wallet with an open Meson swap is still listed, named as Meson', async () => {
  const wallet = '0x' + 'ac'.repeat(20)
  stubMeson({ walletSwaps: [swapRecord(swapId('b'), MOVING)] })
  const world = makeWorld('w5')
  onTicketMessage(world.message(81, world.user, { content: `wallet ${wallet}` }))
  await sleep(300)
  assert.equal(world.posted[0].embeds[0].data.title, 'Unfinished Meson swaps for this wallet: 1')
})

test('a mistyped swap ID still gets "couldn\'t find", not an empty wallet', async () => {
  stubMeson()
  const world = makeWorld('c12')
  onTicketMessage(world.message(74, world.user, { content: `swap 0x${'cd'.repeat(32)}` }))
  await sleep(300)
  assert.equal(world.posted.length, 1)
  assert.ok(world.posted[0].content.startsWith('❓'))
  const [answer, explanation] = world.posted[0].content.split('\n')
  assert.ok(answer.includes('Meson swap'), 'the value stays on the first line, where a restart reads it back')
  assert.ok(explanation.startsWith('-# This only checks swaps made through Meson.'))
  assert.ok(explanation.includes('our support team will respond here'))
})

test('a wallet Meson answers for as a wallet still lists it, with one search first', async () => {
  const wallet = '4'.repeat(40) + 'abcd'
  let searches = 0
  stubMeson({ walletSwaps: [swapRecord(swapId('a'), DONE)] })
  const stubbed = globalThis.fetch
  globalThis.fetch = async (url) => { if (String(url).includes('/search?')) searches++; return stubbed(url) }
  const world = makeWorld('c13')
  onTicketMessage(world.message(75, world.user, { content: `wallet ${wallet}` }))
  await sleep(300)
  assert.equal(searches, 1)
  assert.equal(world.posted[0].embeds[0].data.title, 'No open Meson swaps for this wallet')
})

test('extraction covers the less common chains', () => {
  const short = '0x' + '5'.repeat(63)
  const ton = 'Ab-_'.repeat(10) + 'Ab-'
  assert.deepEqual(extractCandidates(`hash ${short}`), [short])
  assert.ok(extractCandidates(`https://tonviewer.com/transaction/${ton}`).includes(ton))
  const tonWallet = 'EQ' + 'Ab-_'.repeat(11) + 'Ab'
  assert.deepEqual(extractAddressCandidates(`wallet ${tonWallet}`, { allowFallback: false }), [tonWallet])
  const ckbWallet = 'ckb1qzda0cr08m85hc8jlnfp3zer7xulejywt49kt2rr0vthywaa50xwsq'
  assert.deepEqual(extractAddressCandidates(`wallet ${ckbWallet}`, { allowFallback: false }), [ckbWallet])
})
